INSERT INTO `Package` (`id`, `packageName`, `destination`, `duration`, `description`, `price`, `packageType`, `inclusions`, `exclusions`, `imageUrl`, `gallery`, `status`, `createdAt`, `updatedAt`) VALUES ('a7c50257-8bb2-4a93-847d-03456dec67b2', 'Royal Mysore & Coorg Serenity', 'Mysore & Coorg', '4 Days / 3 Nights', 'Immerse in the heritage of the Mysore Wodeyars followed by misty coffee plantations and waterfalls in Coorg.', 24500, 'HOLIDAY', '3 Nights 4-Star Accommodation, Breakfast & Dinner, AC Sedan with chauffeur, Sightseeing transfers, Entry tickets to Mysore Palace', 'Airfare, Personal expenses, Meals not mentioned in inclusions, Camera fees', NULL, NULL, 'ACTIVE', '2026-09-10 05:22:15', '2026-09-10 05:22:15') ON DUPLICATE KEY UPDATE `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `Package` (`id`, `packageName`, `destination`, `duration`, `description`, `price`, `packageType`, `inclusions`, `exclusions`, `imageUrl`, `gallery`, `status`, `createdAt`, `updatedAt`) VALUES ('878b2e3a-3f14-4771-bed3-99de49fa4462', 'Enchanting Ooty & Nilgiris Hills', 'Ooty', '3 Days / 2 Nights', 'Explore the Queen of Hill Stations: botanical gardens, emerald lakes, tea factories, and panoramic viewpoints.', 18500, 'HOLIDAY', '2 Nights Resort Stay, Daily Breakfast, Nilgiri Mountain Toy Train tickets, Private Cab for transfers', 'Lunch/Dinner, Boating charges at Ooty Lake, Personal shopping', NULL, NULL, 'ACTIVE', '2026-09-10 05:22:15', '2026-09-10 05:22:15') ON DUPLICATE KEY UPDATE `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `Package` (`id`, `packageName`, `destination`, `duration`, `description`, `price`, `packageType`, `inclusions`, `exclusions`, `imageUrl`, `gallery`, `status`, `createdAt`, `updatedAt`) VALUES ('6e7f2675-cb73-4cf2-965e-2b6554317b52', 'Andaman Island Paradise & Radhanagar Waters', 'Andaman', '5 Days / 4 Nights', 'Turquoise waters, historic Cellular Jail, and Asia’s best beach at Radhanagar in Havelock Island.', 42000, 'HOLIDAY', '4 Nights Beachfront Resort, Daily Breakfast, Makruzz / Nautika High-Speed Catamaran Ferries, Cellular Jail Light & Sound show', 'Flight tickets, Scuba diving / Snorkeling add-ons, Personal water sports', NULL, NULL, 'ACTIVE', '2026-09-10 05:22:15', '2026-09-10 05:22:15') ON DUPLICATE KEY UPDATE `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `Package` (`id`, `packageName`, `destination`, `duration`, `description`, `price`, `packageType`, `inclusions`, `exclusions`, `imageUrl`, `gallery`, `status`, `createdAt`, `updatedAt`) VALUES ('5f226853-f2dc-4a13-9d5d-56f4b4b269b3', 'Spiritual Kashi & Holy Ayodhya Darshan', 'Ayodhya & Kashi', '4 Days / 3 Nights', 'A deeply moving spiritual journey through sacred Ghats of Varanasi, Ganga Aarti, and the divine Ram Janmabhoomi in Ayodhya.', 28000, 'HOLIDAY', '3 Nights Hotel Stay, Breakfast, VIP Darshan facilitation assistance, Private AC Coach, Sunrise Boat Ride at Varanasi Ghats', 'Prasad offerings, Train/Airfare to Varanasi, Personal expenses', NULL, NULL, 'ACTIVE', '2026-09-10 05:22:15', '2026-09-10 05:22:15') ON DUPLICATE KEY UPDATE `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `ItineraryDay` (`id`, `packageId`, `dayNumber`, `title`, `description`, `activities`, `places`, `startTime`, `endTime`, `imageUrl`, `images`, `createdAt`, `updatedAt`) VALUES ('0d913e4b-2926-448d-a16b-5f55d4c86f52', 'a7c50257-8bb2-4a93-847d-03456dec67b2', 1, 'Arrival in Bangalore to Mysore Heritage', 'Pick up from Bangalore Airport/Station, scenic drive to Mysore. Check-in and visit the illuminated Mysore Palace and Brindavan Gardens musical fountain.', 'Palace architectural tour, evening garden stroll', 'Mysore Palace, Brindavan Gardens', '09:00 AM', '08:00 PM', NULL, NULL, '2026-09-10 05:22:15', '2026-09-10 05:22:15') ON DUPLICATE KEY UPDATE `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `ItineraryDay` (`id`, `packageId`, `dayNumber`, `title`, `description`, `activities`, `places`, `startTime`, `endTime`, `imageUrl`, `images`, `createdAt`, `updatedAt`) VALUES ('b1c788bb-1adc-4d42-b6a3-bfb3c904b261', 'a7c50257-8bb2-4a93-847d-03456dec67b2', 2, 'Chamundi Hills to Coorg Coffee Highlands', 'Visit Chamundi Hill temple, St. Philomena Church, then transfer through winding ghats into Madikeri, Coorg.', 'Temple darshan, scenic hill drive, sunset at Raja Seat', 'Chamundi Temple, St. Philomena Church, Madikeri Fort', '08:30 AM', '07:30 PM', NULL, NULL, '2026-09-10 05:22:15', '2026-09-10 05:22:15') ON DUPLICATE KEY UPDATE `updatedAt` = VALUES(`updatedAt`);
INSERT INTO `ItineraryDay` (`id`, `packageId`, `dayNumber`, `title`, `description`, `activities`, `places`, `startTime`, `endTime`, `imageUrl`, `images`, `createdAt`, `updatedAt`) VALUES ('4dbd3287-3715-487b-a838-4cee5879370d', 'a7c50257-8bb2-4a93-847d-03456dec67b2', 3, 'Abbey Falls & Dubare Elephant Camp', 'Morning interaction with gentle giants at Dubare Camp along Cauvery river, followed by the roar of Abbey Falls and spice plantation walk.', 'Elephant bathing experience, coffee plantation tasting walk', 'Dubare Elephant Camp, Abbey Falls, Coffee Plantation', '08:00 AM', '06:00 PM', NULL, NULL, '2026-09-10 05:22:15', '2026-09-10 05:22:15') ON DUPLICATE KEY UPDATE `updatedAt` = VALUES(`updatedAt`);
